CREATE TABLE IF NOT EXISTS migration_open_item_batches (
  id INTEGER PRIMARY KEY,
  dinero_import_attempt_id INTEGER NOT NULL REFERENCES dinero_import_attempts(id),
  control_account_no TEXT NOT NULL REFERENCES accounts(account_no),
  kind TEXT NOT NULL CHECK(kind IN ('receivable','payable')),
  source_control_amount NUMERIC NOT NULL CHECK(source_control_amount >= 0),
  opening_journal_entry_id INTEGER REFERENCES journal_entries(id),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(dinero_import_attempt_id, control_account_no)
);
CREATE TABLE IF NOT EXISTS migration_open_items (
  id INTEGER PRIMARY KEY,
  batch_id INTEGER NOT NULL REFERENCES migration_open_item_batches(id),
  external_ref TEXT NOT NULL CHECK(length(trim(external_ref)) > 0),
  counterparty_name TEXT,
  issue_date TEXT CHECK(issue_date IS NULL OR length(issue_date) = 10),
  due_date TEXT CHECK(due_date IS NULL OR length(due_date) = 10),
  original_amount NUMERIC NOT NULL CHECK(original_amount > 0),
  open_amount_at_import NUMERIC NOT NULL CHECK(open_amount_at_import > 0 AND open_amount_at_import <= original_amount),
  document_id INTEGER REFERENCES documents(id),
  source_recognition_journal_entry_id INTEGER REFERENCES journal_entries(id),
  source_kind TEXT NOT NULL CHECK(source_kind IN ('opening','journal','control_balance')),
  resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','unallocated')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(batch_id, external_ref),
  UNIQUE(source_recognition_journal_entry_id),
  CHECK((source_kind IN ('opening','control_balance') AND source_recognition_journal_entry_id IS NULL) OR (source_kind = 'journal' AND source_recognition_journal_entry_id IS NOT NULL)),
  CHECK((resolution_status = 'resolved' AND counterparty_name IS NOT NULL AND length(trim(counterparty_name)) > 0 AND issue_date IS NOT NULL) OR (resolution_status = 'unallocated' AND counterparty_name IS NULL AND issue_date IS NULL AND due_date IS NULL AND document_id IS NULL AND source_kind IN ('opening','control_balance')))
);
CREATE TABLE IF NOT EXISTS migration_open_item_applications (
  id INTEGER PRIMARY KEY,
  item_id INTEGER NOT NULL REFERENCES migration_open_items(id),
  amount NUMERIC NOT NULL CHECK(amount > 0),
  application_date TEXT NOT NULL CHECK(length(application_date) = 10),
  source_journal_entry_id INTEGER NOT NULL REFERENCES journal_entries(id),
  bank_transaction_id INTEGER REFERENCES bank_transactions(id),
  note TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_migration_open_item_application_journal ON migration_open_item_applications(source_journal_entry_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_migration_open_item_application_bank ON migration_open_item_applications(bank_transaction_id) WHERE bank_transaction_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_migration_open_items_batch ON migration_open_items(batch_id, external_ref);
CREATE INDEX IF NOT EXISTS idx_migration_open_item_applications_item ON migration_open_item_applications(item_id, id);
CREATE TRIGGER migration_open_item_application_balance_guard BEFORE INSERT ON migration_open_item_applications WHEN CAST(ROUND(100 * (NEW.amount + COALESCE((SELECT SUM(amount) FROM migration_open_item_applications WHERE item_id = NEW.item_id), 0))) AS INTEGER) > CAST(ROUND(100 * (SELECT open_amount_at_import FROM migration_open_items WHERE id = NEW.item_id)) AS INTEGER) BEGIN SELECT RAISE(ABORT, 'migration open-item application would over-apply the open balance'); END;
CREATE TRIGGER migration_open_item_batches_no_update BEFORE UPDATE ON migration_open_item_batches BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_item_batches_no_delete BEFORE DELETE ON migration_open_item_batches BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_items_no_update BEFORE UPDATE ON migration_open_items BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_items_no_delete BEFORE DELETE ON migration_open_items BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_item_applications_no_update BEFORE UPDATE ON migration_open_item_applications BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
CREATE TRIGGER migration_open_item_applications_no_delete BEFORE DELETE ON migration_open_item_applications BEGIN SELECT RAISE(ABORT, 'migration open items are append-only'); END;
